<script setup lang="ts">
import type { components } from '~/api/schema'; import { unwrap, versionHeaders } from '~/api/client'; import { displayError } from '~/utils/errors'; import { formatDate, formatRupiah, statusLabel } from '~/utils/format';
type Order = components['schemas']['OrderGroup']; type PaymentMethod = components['schemas']['PaymentMethod'];
definePageMeta({ middleware: 'auth' }); const api = useMarketplaceApi(); const route = useRoute(); const cartApi = useCart(); const order = ref<Order>(); const stores = ref<Record<string,string>>({}); const methods = ref<PaymentMethod[]>([]); const channel = ref(''); const pending = ref(true); const actionPending = ref(false); const error = ref<unknown>(); const message = ref(''); const showCancel = ref(false); const cancelReason = ref(''); const complaintOrder = ref(''); const complaintKind = ref<'DISPUTE'|'DELIVERY_FAILURE'|'TAX_REVIEW'|'OTHER'>('OTHER'); const complaintReason = ref('');
async function load() { pending.value = true; error.value = undefined; try { if (!cartApi.account.value) await cartApi.load(); order.value = unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/orders/{orderGroupId}', { params: { path: { buyerAccountId: cartApi.account.value!.id, orderGroupId: String(route.params.id) } }, cache: 'no-store' })); const pairs = await Promise.all(order.value.vendor_orders.map(async vendor => { try { const store = unwrap(await api.GET('/stores/{storeId}', { params: { path: { storeId: vendor.store_id } } })); return [vendor.store_id,store.name] as const; } catch { return [vendor.store_id,`Toko ${vendor.store_id.slice(0,8)}`] as const; } })); stores.value = Object.fromEntries(pairs); if (order.value.order_state === 'AWAITING_PAYMENT') { const result = unwrap(await api.GET('/buyer-accounts/{buyerAccountId}/orders/{orderGroupId}/payment-methods', { params: { path: { buyerAccountId: cartApi.account.value!.id, orderGroupId: order.value.id }, query: { limit: 50 } }, cache: 'no-store' })); methods.value = result.items; channel.value = result.items[0]?.code ?? ''; } } catch (cause) { error.value = cause; } finally { pending.value = false; } }
async function startPayment() { if (!order.value || !cartApi.account.value) return; actionPending.value = true; message.value = ''; try { const operation = unwrap(await api.POST('/buyer-accounts/{buyerAccountId}/orders/{orderGroupId}/payment-sessions', { params: { path: { buyerAccountId: cartApi.account.value.id, orderGroupId: order.value.id }, header: { 'Idempotency-Key': crypto.randomUUID() } }, body: channel.value ? { channel: channel.value } : {} })); if (operation.result_id) await navigateTo({ path: `/akun/pembayaran/${operation.result_id}`, query: { operation_id: operation.id, order_id: order.value.id } }); else message.value = 'Sesi pembayaran sedang dibuat. Muat ulang beberapa saat lagi.'; } catch (cause) { message.value = displayError(cause).message; } finally { actionPending.value = false; } }
async function cancelOrder() { if (!order.value || !cartApi.account.value || cancelReason.value.trim().length < 3) return; actionPending.value = true; try { unwrap(await api.POST('/buyer-accounts/{buyerAccountId}/orders/{orderGroupId}/cancel', { params: { path: { buyerAccountId: cartApi.account.value.id, orderGroupId: order.value.id }, header: { ...versionHeaders(order.value.row_version), 'Idempotency-Key': crypto.randomUUID() } }, body: { reason: cancelReason.value } })); showCancel.value = false; message.value = 'Permintaan pembatalan diterima dan sedang diperiksa.'; await load(); } catch (cause) { message.value = displayError(cause).message; } finally { actionPending.value = false; } }
async function confirmReceipt(vendor: Order['vendor_orders'][number]) { if (!cartApi.account.value) return; actionPending.value = true; try { unwrap(await api.POST('/buyer-accounts/{buyerAccountId}/vendor-orders/{vendorOrderId}/receive', { params: { path: { buyerAccountId: cartApi.account.value.id, vendorOrderId: vendor.id }, header: { ...versionHeaders(vendor.row_version), 'Idempotency-Key': crypto.randomUUID() } } })); message.value = 'Penerimaan barang berhasil dikonfirmasi.'; await load(); } catch (cause) { message.value = displayError(cause).message; } finally { actionPending.value = false; } }
async function openCase() { if (!cartApi.account.value || !complaintOrder.value || complaintReason.value.trim().length < 3) return; actionPending.value = true; try { const result = unwrap(await api.POST('/buyer-accounts/{buyerAccountId}/vendor-orders/{vendorOrderId}/cases', { params: { path: { buyerAccountId: cartApi.account.value.id, vendorOrderId: complaintOrder.value }, header: { 'Idempotency-Key': crypto.randomUUID() } }, body: { kind: complaintKind.value, reason: complaintReason.value } })); await navigateTo(`/akun/kasus/${result.id}`); } catch (cause) { message.value = displayError(cause).message; } finally { actionPending.value = false; } }
onMounted(() => { void load(); }); useSeoMeta({ title: computed(() => order.value ? `${order.value.order_number} — Niaga` : 'Detail pesanan — Niaga') });
</script>
<template><main id="main-content" class="page-shell"><BuyerNav/><ApiState :pending="pending" :error="error ? displayError(error) : null" @retry="load"><template v-if="order"><div class="section-heading"><div><p class="eyebrow">Detail pesanan</p><h1>{{ order.order_number }}</h1><p class="muted">Dibuat {{ formatDate(order.created_at) }}</p></div><span class="badge badge--warning">{{ statusLabel(order.order_state) }}</span></div><p v-if="message" class="success" role="status">{{ message }}</p><div class="order-detail-grid"><section class="checkout-steps"><article v-for="vendor in order.vendor_orders" :key="vendor.id" class="surface"><div class="section-heading"><div><h2>{{ stores[vendor.store_id] }}</h2><p>{{ vendor.order_number }}</p></div><span class="badge">{{ statusLabel(vendor.fulfillment_status) }}</span></div><div v-for="item in vendor.items" :key="item.id" class="order-item"><div><strong>{{ item.product_name }}</strong><small>{{ item.sku_code }} · {{ item.quantity }} unit</small></div><div class="money-breakdown"><span>Net {{ formatRupiah(item.line_net) }}</span><span>PPN {{ formatRupiah(item.line_vat) }}</span><strong>{{ formatRupiah(item.line_gross) }}</strong></div></div><div class="form-actions"><NuxtLink v-if="vendor.shipment_id" class="button button--secondary" :to="`/akun/pengiriman/${vendor.shipment_id}`">Lacak pengiriman</NuxtLink><button v-if="vendor.fulfillment_status === 'DELIVERED'" :disabled="actionPending" type="button" @click="confirmReceipt(vendor)">Konfirmasi diterima</button><button class="button--secondary" type="button" @click="complaintOrder = vendor.id">Ajukan komplain</button></div></article><article class="surface"><h2>Alamat transaksi</h2><strong>{{ order.recipient.recipient_name }}</strong><p>{{ order.recipient.phone }}</p><p class="muted">{{ order.recipient.street }}<br>{{ order.recipient.district }}, {{ order.recipient.city }}, {{ order.recipient.province }} {{ order.recipient.postal_code }}</p></article><form v-if="complaintOrder" class="surface" @submit.prevent="openCase"><h2>Ajukan komplain</h2><label class="form-field">Jenis masalah<select v-model="complaintKind"><option value="DISPUTE">Masalah produk/transaksi</option><option value="DELIVERY_FAILURE">Masalah pengiriman</option><option value="TAX_REVIEW">Masalah pajak</option><option value="OTHER">Lainnya</option></select></label><label class="form-field">Alasan<textarea v-model.trim="complaintReason" required minlength="3" maxlength="2000" rows="4"/></label><div class="form-actions"><button :disabled="actionPending || complaintReason.length < 3">Kirim komplain</button><button class="button--secondary" type="button" @click="complaintOrder = ''">Batal</button></div></form></section><aside class="surface order-summary"><h2>Pembayaran</h2><span class="badge" :class="{ 'badge--warning': order.payment_status !== 'PAID' }">{{ statusLabel(order.payment_status) }}</span><div class="summary-line"><span>Produk</span><span>{{ formatRupiah(order.totals.items_gross) }}</span></div><div class="summary-line"><span>PPN termasuk</span><span>{{ formatRupiah(order.totals.items_vat) }}</span></div><div class="summary-line"><span>Ongkir</span><span>{{ formatRupiah(order.totals.shipping) }}</span></div><div class="summary-line"><span>Biaya pembeli</span><span>{{ formatRupiah(order.totals.buyer_fee) }}</span></div><div class="summary-line summary-total"><strong>Total</strong><strong>{{ formatRupiah(order.totals.grand_total) }}</strong></div><template v-if="order.order_state === 'AWAITING_PAYMENT'"><label class="form-field">Metode pembayaran<select v-model="channel"><option v-for="method in methods" :key="method.code" :value="method.code">{{ method.name }}</option></select></label><button :disabled="actionPending || !channel" @click="startPayment">{{ actionPending ? 'Memproses…' : 'Bayar sekarang' }}</button><button class="text-button" type="button" @click="showCancel = true">Minta pembatalan</button></template><NuxtLink to="/akun/refund">Lihat status refund</NuxtLink></aside></div><form v-if="showCancel" class="surface section" @submit.prevent="cancelOrder"><h2>Konfirmasi pembatalan</h2><p>Permintaan akan diverifikasi terhadap status provider sebelum stok dilepas.</p><label class="form-field">Alasan<textarea v-model.trim="cancelReason" required minlength="3" maxlength="2000" rows="3"/></label><div class="form-actions"><button :disabled="actionPending || cancelReason.length < 3">Ajukan pembatalan</button><button class="button--secondary" type="button" @click="showCancel = false">Kembali</button></div></form></template></ApiState></main></template>
